//! 🧪️ Native receiving relays every original owned cause without flattening the effect boundary.
use semio_framework_value_native_outcome::*;
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
fn owned(text:&str)->ValueError{ValueError::new(ValueRefusalKind::Canceled,text.to_owned())}
#[test]
fn native_receiving_failure_wraps_the_complete_original_effect_without_allocation_or_overwrite(){
 let law:serde_json::Value=serde_json::from_str(include_str!("failure.json")).unwrap();let labels=law["causes"].as_array().unwrap();let mut errors=labels.iter().map(|label|owned(label.as_str().unwrap())).collect::<Vec<_>>().into_iter();let first=errors.next().unwrap();let mut receiving=OriginalReceivingPrimary::from(first);assert!(receiving.receipt_completion().is_none());receiving.work_refusal=Some(errors.next().unwrap());receiving.retirement_failure=Some(OriginalRetirementFailure::from(errors.next().unwrap()));receiving.progress=RetainedCloneProgress{copied_items:2,copied_bytes:3,..Default::default()};
 let failure=NativeReceivingEffectFailure{receiving,child:Some(OriginalRetirementFailure::from(errors.next().unwrap())),producer_refusal:Some(errors.next().unwrap()),work_refusal:Some(errors.next().unwrap())};let pointers=[failure.receiving.primary.as_ref().unwrap().message.as_ptr(),failure.receiving.work_refusal.as_ref().unwrap().message.as_ptr(),failure.receiving.retirement_failure.as_ref().unwrap().primary().unwrap().message.as_ptr(),failure.child.as_ref().unwrap().primary().unwrap().message.as_ptr(),failure.producer_refusal.as_ref().unwrap().message.as_ptr(),failure.work_refusal.as_ref().unwrap().message.as_ptr()];
 let(wrapped,heap)=observe(||NativeReceivingFailure::RetirementEffect(failure));assert_eq!(heap,(0,0));assert_eq!(wrapped.retained_progress(),RetainedCloneProgress{copied_items:2,copied_bytes:3,..Default::default()});let NativeReceivingFailure::RetirementEffect(failure)=wrapped else{panic!("original native effect tag changed")};let actual=[failure.receiving.primary.as_ref().unwrap(),failure.receiving.work_refusal.as_ref().unwrap(),failure.receiving.retirement_failure.as_ref().unwrap().primary().unwrap(),failure.child.as_ref().unwrap().primary().unwrap(),failure.producer_refusal.as_ref().unwrap(),failure.work_refusal.as_ref().unwrap()];for(index,error)in actual.iter().enumerate(){assert_eq!(error.message.as_ptr(),pointers[index])}assert_eq!(serde_json::to_value(actual.map(|error|error.message.as_ref())).unwrap(),law["causes"]);
}
#[test]
fn pure_native_guards_and_each_effect_domain_keep_their_actual_tag(){
 let primary:NativeReceivingFailure=owned("guard").into();assert!(matches!(primary,NativeReceivingFailure::Primary(_)));let primary:NativeReceivingFailure=OriginalReceivingPrimary::from(owned("primary")).into();assert!(matches!(primary,NativeReceivingFailure::Primary(_)));
 let value=NativeReceivingEffectFailure{child:Some(owned("value")),producer_refusal:None,work_refusal:None,receiving:owned("enclosing").into()};assert!(matches!(NativeReceivingFailure::from(value),NativeReceivingFailure::ValueEffect(_)));
 let receiving=NativeReceivingEffectFailure{child:Some(OriginalReceivingPrimary::from(owned("child"))),producer_refusal:None,work_refusal:None,receiving:owned("enclosing").into()};assert!(matches!(NativeReceivingFailure::from(receiving),NativeReceivingFailure::ReceivingEffect(_)));
}

struct CompletionWork;
impl semio_framework_value_control_contract::OriginalWorkRecipient for CompletionWork{
 type Context<'a,'b>=() where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&())->Result<(),ValueError> where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,_:&())->Option<semio_framework_value_control_contract::OriginalSourceTurnIdentity> where 'b:'a{None}
 fn admits<'r,'a,'b>(&mut self,_:&mut (),q:semio_framework_value_control_contract::OriginalWorkQuote<'r>,_:u64,_:u64)->semio_framework_value_control_contract::OriginalWorkQuoteComplete<'r> where 'b:'a{q.complete(Ok(true))}
 fn settle_partial<'r,'a,'b>(&mut self,_:&mut (),q:semio_framework_value_control_contract::OriginalWorkPartialCheck<'r>)->semio_framework_value_control_contract::OriginalWorkPartialCheckComplete<'r> where 'b:'a{q.complete(Ok(()))}
 fn recover_partial<'r,'a,'b>(&mut self,_:&mut (),q:semio_framework_value_control_contract::OriginalWorkPartialCheck<'r>)->semio_framework_value_control_contract::OriginalWorkPartialCheckComplete<'r> where 'b:'a{q.pending()}
}
struct CompletionPhysical{original:Option<ValueError>,payout:Option<ValueError>,calls:usize}
impl semio_framework_value_control_contract::OriginalConstructionRecipient for CompletionPhysical{
 type Context<'a,'b>=() where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&())->Result<(),ValueError> where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,_:&())->Option<semio_framework_value_control_contract::OriginalSourceTurnIdentity> where 'b:'a{None}
 fn grant<'r,'a,'b>(&mut self,_:&mut (),q:semio_framework_value_control_contract::OriginalConstructionGrant<'r>)->semio_framework_value_control_contract::OriginalConstructionGrantComplete<'r> where 'b:'a{q.complete(Ok(semio_framework_value_control_contract::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:1,..Default::default()}))}
 fn accept<'r,'a,'b>(&mut self,_:&mut (),r:semio_framework_value_control_contract::OriginalConstructionAccept<'r>)->semio_framework_value_control_contract::OriginalConstructionAcceptComplete<'r> where 'b:'a{self.calls+=1;if self.calls==1{return r.complete(Err(self.original.take().unwrap()))}if self.calls==3{if let Some(error)=self.payout.take(){let _recorded=r.complete(Err(error));panic!("receiving completion payout interrupted after refusal")}}r.complete(Ok(()))}
 fn submitted<'a,'b>(&self,_:&())->RetainedCloneProgress where 'b:'a{Default::default()}
}
fn completion_payment(loan:&mut semio_framework_value_control_contract::OriginalConstructionLoan<'_>,work:&mut semio_framework_value_control_contract::OriginalWork<'_>,demand:semio_framework_value_control_contract::RetirementDemand,operation:impl FnOnce(&mut semio_framework_value_control_contract::OriginalConstructionLoan<'_>,&semio_framework_value_control_contract::OriginalConstructionAction,&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>)->semio_framework_value_control_contract::RetainedWorkOutcome<Option<RetainedCloneProgress>,ValueError>)->(Option<semio_framework_value_control_contract::OriginalConstructionAction>,Option<semio_framework_value_control_contract::OriginalWorkActionProof>,Option<semio_framework_value_control_contract::OriginalWorkActionIdentity>){
 use semio_framework_value_control_contract as core;let(mut payout,mut action,mut receipt,mut proof,mut actual)=(None,None,None,None,None);loan.begin(demand,&mut payout,&core::OriginalWorkBorrow::new(work)).unwrap();loan.quote(payout.as_mut().unwrap()).unwrap();let grant=loan.recover_grant(payout.as_mut().unwrap()).unwrap().unwrap().unwrap();assert_eq!(work.prepare_for_action(1,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();let progress={let mut effect=core::RetainedAllocationEffect::new(grant,1,&mut actual,receipt.as_mut().unwrap());operation(loan,payout.as_ref().unwrap(),&mut effect).result.unwrap().unwrap()};work.claim_performed_for_action(action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());assert!(partial.as_ref().unwrap().source_refusal().is_none());drop(partial);assert!(work.commit_for_action(1,action,&mut proof).unwrap());loan.post(payout.as_mut().unwrap(),progress,None).unwrap();assert_eq!(loan.recover_accept(payout.as_mut().unwrap()).unwrap(),Some(core::OriginalConstructionAcceptStatus::Accepted));(payout,proof,action)
}
#[test]
fn receiving_primary_keeps_published_original_completion_until_paid_retirement(){
 use semio_framework_value_control_contract as core;use semio_framework_value_retirement::retirement::RetireOwned;let error=ValueError::new(ValueRefusalKind::Canceled,String::from("published receipt owner"));let pointer=error.message.as_ptr();let mut physical=core::OriginalConstructionAuthority::new(CompletionPhysical{original:Some(error),payout:None,calls:0});let mut payer=core::OriginalWorkAuthority::new(CompletionWork);let(mut original,mut completion)=(None,None);let mut receiving=OriginalReceivingPrimary::from_fields(None,None,None,None,None,None,None,None,None,Default::default());
 payer.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=core::OriginalWork::empty();work.recipient=Some(&mut loan);physical.with_loan(&mut (),|physical|{physical.begin(Default::default(),&mut original,&core::OriginalWorkBorrow::new(&mut work)).unwrap();physical.quote(original.as_mut().unwrap()).unwrap();physical.recover_grant(original.as_mut().unwrap()).unwrap().unwrap().unwrap();physical.post(original.as_mut().unwrap(),Default::default(),None).unwrap();assert_eq!(physical.recover_accept(original.as_mut().unwrap()).unwrap(),Some(core::OriginalConstructionAcceptStatus::Refused));let(mut payout,mut proof,mut action)=completion_payment(physical,&mut work,core::OriginalConstructionCompletion::demand(),|loan,payout,effect|{let witness=loan.witness(payout).unwrap();loan.stage_completion(&mut original,&mut completion,&witness,effect)});assert!(physical.publish_completion(completion.as_mut().unwrap(),payout.as_mut().unwrap(),&core::OriginalWorkBorrow::new(&mut work),proof.as_ref().unwrap()).unwrap());physical.finish_accepted(&mut payout).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap();let demand=OriginalReceivingPrimary::receipt_completion_demand();let(mut denied,mut denied_action,mut denied_receipt,mut denied_actual)=(None,None,None,None);physical.begin(demand,&mut denied,&core::OriginalWorkBorrow::new(&mut work)).unwrap();physical.quote(denied.as_mut().unwrap()).unwrap();let grant=physical.recover_grant(denied.as_mut().unwrap()).unwrap().unwrap().unwrap();assert_eq!(work.prepare_for_action(1,&mut denied_action).unwrap(),Some(true));work.issue_performed_for_action(denied_action,&mut denied_receipt).unwrap();{let mut effect=core::RetainedAllocationEffect::new(grant,0,&mut denied_actual,denied_receipt.as_mut().unwrap());let turn=receiving.stage_receipt_completion(&mut completion,physical,denied.as_ref().unwrap(),&mut effect);assert!(turn.result.unwrap().is_none());assert_eq!(turn.work,0)}assert!(completion.is_some());assert!(!receiving.receipt_completion_pending());work.claim_performed_for_action(denied_action,&mut denied_receipt).unwrap();work.cancel_for_action(&mut denied_action).unwrap();physical.cancel(denied.as_mut().unwrap(),false,Default::default(),None).unwrap();physical.finish(&mut denied).unwrap();let mut foreign=core::OriginalWorkAuthority::new(CompletionWork);foreign.with_loan(&mut (),|foreign_loan|{let mut foreign_loan=foreign_loan.reborrow();let mut foreign_work=core::OriginalWork::empty();foreign_work.recipient=Some(&mut foreign_loan);let(mut foreign_action,mut foreign_receipt,mut foreign_actual)=(None,None,None);physical.begin(demand,&mut denied,&core::OriginalWorkBorrow::new(&mut work)).unwrap();physical.quote(denied.as_mut().unwrap()).unwrap();let grant=physical.recover_grant(denied.as_mut().unwrap()).unwrap().unwrap().unwrap();assert_eq!(foreign_work.prepare_for_action(1,&mut foreign_action).unwrap(),Some(true));foreign_work.issue_performed_for_action(foreign_action,&mut foreign_receipt).unwrap();{let mut effect=core::RetainedAllocationEffect::new(grant,1,&mut foreign_actual,foreign_receipt.as_mut().unwrap());assert!(receiving.stage_receipt_completion(&mut completion,physical,denied.as_ref().unwrap(),&mut effect).result.is_err())}assert!(completion.is_some());assert!(!receiving.receipt_completion_pending());foreign_work.claim_performed_for_action(foreign_action,&mut foreign_receipt).unwrap();foreign_work.cancel_for_action(&mut foreign_action).unwrap();physical.cancel(denied.as_mut().unwrap(),false,Default::default(),None).unwrap();physical.finish(&mut denied).unwrap()}).unwrap();let(mut payout,mut proof,mut action)=completion_payment(physical,&mut work,OriginalReceivingPrimary::receipt_completion_demand(),|loan,payout,effect|receiving.stage_receipt_completion(&mut completion,loan,payout,effect));assert!(receiving.receipt_completion_pending());assert!(receiving.receipt_completion().is_none());assert!(!receiving.retirement_ready());assert!(receiving.publish_receipt_completion(physical,payout.as_ref().unwrap(),&core::OriginalWorkBorrow::new(&mut work),proof.as_ref().unwrap()).unwrap());assert_eq!(receiving.receipt_completion().unwrap().message.as_ptr(),pointer);assert!(!receiving.retirement_ready());physical.finish_accepted(&mut payout).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap();let demand=receiving.receipt_completion_release_demand().unwrap().unwrap();let(mut payout,mut proof,mut action)=completion_payment(physical,&mut work,demand,|loan,payout,effect|receiving.retire_receipt_completion(loan,payout,effect));assert!(receiving.receipt_completion().is_none());assert!(receiving.retirement_ready());physical.finish_accepted(&mut payout).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap()}).unwrap()}).unwrap();assert!(completion.is_none());assert!(original.is_none());assert!(physical.into_recipient().is_ok());
}

fn completion_refused_payment(loan:&mut semio_framework_value_control_contract::OriginalConstructionLoan<'_>,work:&mut semio_framework_value_control_contract::OriginalWork<'_>,demand:semio_framework_value_control_contract::RetirementDemand,operation:impl FnOnce(&mut semio_framework_value_control_contract::OriginalConstructionLoan<'_>,&semio_framework_value_control_contract::OriginalConstructionAction,&mut semio_framework_value_control_contract::RetainedAllocationEffect<'_>)->semio_framework_value_control_contract::RetainedWorkOutcome<Option<RetainedCloneProgress>,ValueError>)->(Option<semio_framework_value_control_contract::OriginalConstructionAction>,Option<semio_framework_value_control_contract::OriginalWorkActionProof>,Option<semio_framework_value_control_contract::OriginalWorkActionIdentity>){
 use semio_framework_value_control_contract as core;let(mut payout,mut action,mut receipt,mut proof,mut actual)=(None,None,None,None,None);loan.begin(demand,&mut payout,&core::OriginalWorkBorrow::new(work)).unwrap();loan.quote(payout.as_mut().unwrap()).unwrap();let grant=loan.recover_grant(payout.as_mut().unwrap()).unwrap().unwrap().unwrap();assert_eq!(work.prepare_for_action(1,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();let progress={let mut effect=core::RetainedAllocationEffect::new(grant,1,&mut actual,receipt.as_mut().unwrap());operation(loan,payout.as_ref().unwrap(),&mut effect).result.unwrap().unwrap()};work.claim_performed_for_action(action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());assert!(partial.as_ref().unwrap().source_refusal().is_none());drop(partial);assert!(work.commit_for_action(1,action,&mut proof).unwrap());assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||loan.post(payout.as_mut().unwrap(),progress,None))).is_err());assert_eq!(loan.recover_accept(payout.as_mut().unwrap()).unwrap(),Some(core::OriginalConstructionAcceptStatus::Refused));(payout,proof,action)
}
#[test]
fn receiving_primary_preserves_original_and_interrupted_payout_refusals(){
 use semio_framework_value_control_contract as core;use semio_framework_value_retirement::retirement::RetireOwned;let original_error=ValueError::new(ValueRefusalKind::Canceled,String::from("original receiving receipt"));let original_pointer=original_error.message.as_ptr();let payout_error=ValueError::new(ValueRefusalKind::WorkLimit,String::from("separate receiving payout refusal"));let payout_pointer=payout_error.message.as_ptr();let mut physical=core::OriginalConstructionAuthority::new(CompletionPhysical{original:Some(original_error),payout:Some(payout_error),calls:0});let mut payer=core::OriginalWorkAuthority::new(CompletionWork);let(mut original,mut completion,mut payout_failure)=(None,None,None);let mut receiving=OriginalReceivingPrimary::from_fields(None,None,None,None,None,None,None,None,None,Default::default());
 payer.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=core::OriginalWork::empty();work.recipient=Some(&mut loan);physical.with_loan(&mut (),|physical|{
  physical.begin(Default::default(),&mut original,&core::OriginalWorkBorrow::new(&mut work)).unwrap();physical.quote(original.as_mut().unwrap()).unwrap();physical.recover_grant(original.as_mut().unwrap()).unwrap().unwrap().unwrap();physical.post(original.as_mut().unwrap(),Default::default(),None).unwrap();assert_eq!(physical.recover_accept(original.as_mut().unwrap()).unwrap(),Some(core::OriginalConstructionAcceptStatus::Refused));let original_identity=original.as_ref().unwrap().identity();
  let(mut payout,mut proof,mut action)=completion_payment(physical,&mut work,core::OriginalConstructionCompletion::demand(),|loan,payout,effect|{let witness=loan.witness(payout).unwrap();loan.stage_completion(&mut original,&mut completion,&witness,effect)});assert!(physical.publish_completion(completion.as_mut().unwrap(),payout.as_mut().unwrap(),&core::OriginalWorkBorrow::new(&mut work),proof.as_ref().unwrap()).unwrap());physical.finish_accepted(&mut payout).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap();
  let(mut rejected,mut proof,mut action)=completion_refused_payment(physical,&mut work,OriginalReceivingPrimary::receipt_completion_demand(),|loan,payout,effect|receiving.stage_receipt_completion(&mut completion,loan,payout,effect));assert!(!receiving.publish_receipt_completion(physical,rejected.as_ref().unwrap(),&core::OriginalWorkBorrow::new(&mut work),proof.as_ref().unwrap()).unwrap());assert!(receiving.receipt_completion_pending());assert!(receiving.receipt_completion().is_none());assert!(!receiving.retirement_ready());work.finish_for_action(&mut proof,&mut action).unwrap();
  let rejected_identity=rejected.as_ref().unwrap().identity();let(mut payout,mut proof,mut action)=completion_payment(physical,&mut work,core::OriginalConstructionCompletion::demand(),|loan,payout,effect|{let witness=loan.witness(payout).unwrap();loan.stage_completion(&mut rejected,&mut payout_failure,&witness,effect)});assert!(receiving.receipt_retry_witness(physical,payout_failure.as_ref().unwrap()).unwrap().is_none());assert!(physical.publish_completion(payout_failure.as_mut().unwrap(),payout.as_mut().unwrap(),&core::OriginalWorkBorrow::new(&mut work),proof.as_ref().unwrap()).unwrap());assert_eq!(payout_failure.as_ref().unwrap().refusal().unwrap().message.as_ptr(),payout_pointer);physical.finish_accepted(&mut payout).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap();
  let mut foreign=core::OriginalConstructionAuthority::new(CompletionPhysical{original:None,payout:None,calls:0});foreign.with_loan(&mut (),|other|{assert!(receiving.receipt_retry_witness(other,payout_failure.as_ref().unwrap()).is_err())}).unwrap();assert!(foreign.into_recipient().is_ok());let witness=receiving.receipt_retry_witness(physical,payout_failure.as_ref().unwrap()).unwrap().unwrap();assert_eq!(witness.original_identity(),original_identity);assert_eq!(witness.refusal_identity(),rejected_identity);drop(witness);let(mut payout,mut proof,mut action)=completion_payment(physical,&mut work,OriginalReceivingPrimary::receipt_completion_retry_demand(),|loan,payout,effect|receiving.retry_receipt_completion(payout_failure.as_ref().unwrap(),loan,payout,effect));assert!(receiving.publish_receipt_completion(physical,payout.as_ref().unwrap(),&core::OriginalWorkBorrow::new(&mut work),proof.as_ref().unwrap()).unwrap());assert_eq!(receiving.receipt_completion().unwrap().message.as_ptr(),original_pointer);assert_eq!(payout_failure.as_ref().unwrap().refusal().unwrap().message.as_ptr(),payout_pointer);physical.finish_accepted(&mut payout).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap();
  let demand=receiving.receipt_completion_release_demand().unwrap().unwrap();let(mut payout,mut proof,mut action)=completion_payment(physical,&mut work,demand,|loan,payout,effect|{let(turn,heap)=observe(||receiving.retire_receipt_completion(loan,payout,effect));assert_eq!(heap,(0,demand.release_bytes));turn});physical.finish_accepted(&mut payout).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap();let demand=payout_failure.as_ref().unwrap().release_demand();let(mut payout,mut proof,mut action)=completion_payment(physical,&mut work,demand,|loan,payout,effect|{let(turn,heap)=observe(||loan.retire_completion(&mut payout_failure,payout,effect));assert_eq!(heap,(0,demand.release_bytes));turn});physical.finish_accepted(&mut payout).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap();assert!(receiving.retirement_ready());
 }).unwrap()}).unwrap();assert!(completion.is_none());assert!(payout_failure.is_none());assert!(physical.into_recipient().is_ok());
}

struct InitialPayoutPhysical{original:Option<ValueError>,payout:Option<ValueError>,calls:usize}
impl semio_framework_value_control_contract::OriginalConstructionRecipient for InitialPayoutPhysical{
 type Context<'a,'b>=() where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&())->Result<(),ValueError> where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,_:&())->Option<semio_framework_value_control_contract::OriginalSourceTurnIdentity> where 'b:'a{None}
 fn grant<'r,'a,'b>(&mut self,_:&mut (),q:semio_framework_value_control_contract::OriginalConstructionGrant<'r>)->semio_framework_value_control_contract::OriginalConstructionGrantComplete<'r> where 'b:'a{q.complete(Ok(semio_framework_value_control_contract::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:1,..Default::default()}))}
 fn accept<'r,'a,'b>(&mut self,_:&mut (),r:semio_framework_value_control_contract::OriginalConstructionAccept<'r>)->semio_framework_value_control_contract::OriginalConstructionAcceptComplete<'r> where 'b:'a{self.calls+=1;if self.calls==1{return r.complete(Err(self.original.take().unwrap()))}if self.calls==2{let recorded=r.complete(Err(self.payout.take().unwrap()));drop(recorded);panic!("original completion payout interrupted after refusal")}r.complete(Ok(()))}
 fn submitted<'a,'b>(&self,_:&())->RetainedCloneProgress where 'b:'a{Default::default()}
}
#[test]
fn original_completion_retry_witness_keeps_both_refusals(){
 use semio_framework_value_control_contract as core;let original_error=ValueError::new(ValueRefusalKind::Canceled,String::from("original terminal receipt"));let original_pointer=original_error.message.as_ptr();let payout_error=ValueError::new(ValueRefusalKind::WorkLimit,String::from("original payout refusal"));let payout_pointer=payout_error.message.as_ptr();let mut physical=core::OriginalConstructionAuthority::new(InitialPayoutPhysical{original:Some(original_error),payout:Some(payout_error),calls:0});let mut payer=core::OriginalWorkAuthority::new(CompletionWork);let(mut original,mut completion,mut rejected_completion,mut retried)=(None,None,None,None);payer.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=core::OriginalWork::empty();work.recipient=Some(&mut loan);physical.with_loan(&mut (),|physical|{
 physical.begin(Default::default(),&mut original,&core::OriginalWorkBorrow::new(&mut work)).unwrap();let original_identity=original.as_ref().unwrap().identity();physical.quote(original.as_mut().unwrap()).unwrap();physical.recover_grant(original.as_mut().unwrap()).unwrap().unwrap().unwrap();physical.post(original.as_mut().unwrap(),Default::default(),None).unwrap();assert_eq!(physical.recover_accept(original.as_mut().unwrap()).unwrap(),Some(core::OriginalConstructionAcceptStatus::Refused));
 let(mut rejected,mut proof,mut action)=completion_refused_payment(physical,&mut work,core::OriginalConstructionCompletion::demand(),|loan,payout,effect|{let witness=loan.witness(payout).unwrap();loan.stage_completion(&mut original,&mut completion,&witness,effect)});let rejected_identity=rejected.as_ref().unwrap().identity();work.finish_for_action(&mut proof,&mut action).unwrap();
 let(mut capture,mut proof,mut action)=completion_payment(physical,&mut work,core::OriginalConstructionCompletion::demand(),|loan,payout,effect|{let witness=loan.witness(payout).unwrap();loan.stage_completion(&mut rejected,&mut rejected_completion,&witness,effect)});assert!(physical.completion_retry_witness(completion.as_ref().unwrap(),rejected_completion.as_ref().unwrap()).unwrap().is_none());assert!(physical.publish_completion(rejected_completion.as_mut().unwrap(),capture.as_mut().unwrap(),&core::OriginalWorkBorrow::new(&mut work),proof.as_ref().unwrap()).unwrap());physical.finish_accepted(&mut capture).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap();let mut foreign=core::OriginalConstructionAuthority::new(CompletionPhysical{original:None,payout:None,calls:0});foreign.with_loan(&mut (),|other|{assert!(other.completion_retry_witness(completion.as_ref().unwrap(),rejected_completion.as_ref().unwrap()).is_err())}).unwrap();assert!(foreign.into_recipient().is_ok());let witness=physical.completion_retry_witness(completion.as_ref().unwrap(),rejected_completion.as_ref().unwrap()).unwrap().unwrap();assert_eq!(witness.original_identity(),original_identity);assert_eq!(witness.refusal_identity(),rejected_identity);drop(witness);
 let(mut retry,mut proof,mut action)=completion_payment(physical,&mut work,core::OriginalConstructionCompletion::restage_demand(),|loan,payout,effect|{let witness=loan.witness(payout).unwrap();loan.restage_completion(&mut completion,&mut retried,rejected_completion.as_ref().unwrap(),&witness,effect)});assert!(physical.publish_completion(retried.as_mut().unwrap(),retry.as_mut().unwrap(),&core::OriginalWorkBorrow::new(&mut work),proof.as_ref().unwrap()).unwrap());assert_eq!(retried.as_ref().unwrap().refusal().unwrap().message.as_ptr(),original_pointer);assert_eq!(rejected_completion.as_ref().unwrap().refusal().unwrap().message.as_ptr(),payout_pointer);physical.finish_accepted(&mut retry).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap();
 for slot in [&mut retried,&mut rejected_completion]{let demand=slot.as_ref().unwrap().release_demand();let(mut payout,mut proof,mut action)=completion_payment(physical,&mut work,demand,|loan,payout,effect|loan.retire_completion(slot,payout,effect));physical.finish_accepted(&mut payout).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap();}
 }).unwrap()}).unwrap();assert!(physical.into_recipient().is_ok());
}
